const router = require('express').Router();
const db = require('../db');

router.get('/', async (req, res) => {
  const { rows } = await db.query('SELECT * FROM orders ORDER BY id DESC LIMIT 50');
  res.json(rows);
});

router.post('/', async (req, res) => {
  const { customerId, total } = req.body;
  const { rows } = await db.query('INSERT INTO orders(customer_id, total) VALUES ($1, $2) RETURNING *', [customerId, total]);
  res.status(201).json(rows[0]);
});

module.exports = router;

