const db = require('../db');

module.exports = function (app) {
  app.get('/invoices/:id', function (req, res) {
    db.query('SELECT * FROM invoices WHERE id = $1', [req.params.id]).then(function (r) { res.json(r.rows[0]); });
  });
};

